CREATE OR REPLACE FUNCTION public.photo_training_access(t uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND NOT public.is_login_blocked() AND EXISTS(SELECT 1 FROM public.user_company_access WHERE user_id=auth.uid() AND tenant_id=t AND is_active=true) $$;
REVOKE ALL ON FUNCTION public.photo_training_access(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.photo_training_access(uuid) TO authenticated,service_role;
CREATE TABLE public.photo_training_originals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, property_id text NOT NULL, sha256 text NOT NULL, storage_path text NOT NULL, file_name text NOT NULL, width integer NOT NULL, height integer NOT NULL, uploaded_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,sha256), UNIQUE(tenant_id,storage_path));
GRANT SELECT ON public.photo_training_originals TO authenticated; GRANT ALL ON public.photo_training_originals TO service_role;
ALTER TABLE public.photo_training_originals ENABLE ROW LEVEL SECURITY;
CREATE POLICY training_originals_read ON public.photo_training_originals FOR SELECT TO authenticated USING(public.photo_training_access(tenant_id));
CREATE TABLE public.photo_training_labels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, original_id uuid NOT NULL REFERENCES public.photo_training_originals(id), roof_system text NOT NULL, regions jsonb NOT NULL DEFAULT '[]', annotations jsonb NOT NULL DEFAULT '{}', no_visible_damage boolean NOT NULL DEFAULT false, tags text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'draft', revision integer NOT NULL DEFAULT 1, labeled_by uuid NOT NULL, approved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(original_id));
GRANT SELECT ON public.photo_training_labels TO authenticated; GRANT ALL ON public.photo_training_labels TO service_role;
ALTER TABLE public.photo_training_labels ENABLE ROW LEVEL SECURITY;
CREATE POLICY training_labels_read ON public.photo_training_labels FOR SELECT TO authenticated USING(public.photo_training_access(tenant_id));
CREATE TABLE public.photo_training_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL, label_id uuid REFERENCES public.photo_training_labels(id), model_id uuid, action text NOT NULL, revision integer, snapshot jsonb NOT NULL DEFAULT '{}', notes text, actor_id uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.photo_training_events TO authenticated; GRANT ALL ON public.photo_training_events TO service_role;
ALTER TABLE public.photo_training_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY training_events_read ON public.photo_training_events FOR SELECT TO authenticated USING(public.photo_training_access(tenant_id));
CREATE TABLE public.photo_training_datasets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,version text NOT NULL,manifest jsonb NOT NULL,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,version));
GRANT SELECT ON public.photo_training_datasets TO authenticated; GRANT ALL ON public.photo_training_datasets TO service_role;
ALTER TABLE public.photo_training_datasets ENABLE ROW LEVEL SECURITY;
CREATE POLICY training_datasets_read ON public.photo_training_datasets FOR SELECT TO authenticated USING(public.photo_training_access(tenant_id));
CREATE TABLE public.photo_damage_models(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,dataset_id uuid NOT NULL REFERENCES public.photo_training_datasets(id),version text NOT NULL, framework text NOT NULL DEFAULT 'torchvision-fasterrcnn', configuration jsonb NOT NULL, checkpoint_sha256 text NOT NULL, checkpoint_path text NOT NULL,license_evidence text NOT NULL,license_approved_by uuid,metrics jsonb,status text NOT NULL DEFAULT 'trained_unvalidated',created_by uuid NOT NULL DEFAULT auth.uid(),approved_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,version));
GRANT SELECT ON public.photo_damage_models TO authenticated; GRANT ALL ON public.photo_damage_models TO service_role;
ALTER TABLE public.photo_damage_models ENABLE ROW LEVEL SECURITY;
CREATE POLICY training_models_read ON public.photo_damage_models FOR SELECT TO authenticated USING(public.photo_training_access(tenant_id));
CREATE TABLE public.photo_damage_deployments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,model_id uuid NOT NULL REFERENCES public.photo_damage_models(id),previous_model_id uuid REFERENCES public.photo_damage_models(id),action text NOT NULL,actor_id uuid NOT NULL DEFAULT auth.uid(),notes text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.photo_damage_deployments TO authenticated; GRANT ALL ON public.photo_damage_deployments TO service_role;
ALTER TABLE public.photo_damage_deployments ENABLE ROW LEVEL SECURITY;
CREATE POLICY training_deployments_read ON public.photo_damage_deployments FOR SELECT TO authenticated USING(public.photo_training_access(tenant_id));
CREATE POLICY training_original_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='photo-training-originals' AND public.photo_training_access((storage.foldername(name))[1]::uuid) AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp'));
CREATE POLICY training_original_download ON storage.objects FOR SELECT TO authenticated USING(bucket_id='photo-training-originals' AND public.photo_training_access((storage.foldername(name))[1]::uuid));
CREATE OR REPLACE FUNCTION public.photo_training_class_valid(s text,c text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE s WHEN 'shingle' THEN c=ANY(ARRAY['missing_shingles','displaced_shingles','creased_shingles','torn_shingles','exposed_underlayment','ridge_cap_loss']) WHEN 'clay_tile' THEN c=ANY(ARRAY['cracked_tile','broken_tile','displaced_tile','missing_tile','ridge_tile_damage','exposed_underlayment']) WHEN 'concrete_tile' THEN c=ANY(ARRAY['cracked_tile','broken_tile','displaced_tile','missing_tile','ridge_tile_damage','exposed_underlayment']) WHEN 'metal' THEN c=ANY(ARRAY['displaced_panel','open_seam','loose_flashing','panel_deformation','missing_component']) WHEN 'flat' THEN c=ANY(ARRAY['membrane_tear','membrane_puncture','open_seam','displaced_flashing','membrane_blister','exposed_substrate']) WHEN 'envelope' THEN c=ANY(ARRAY['missing_siding','torn_house_wrap','exposed_sheathing','damaged_fascia','damaged_soffit','damaged_flashing']) ELSE false END $$;
REVOKE ALL ON FUNCTION public.photo_training_class_valid(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.photo_training_class_valid(text,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.photo_training_original_add(t uuid,property text,hash text,path text,name text,w integer,h integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid; BEGIN
IF NOT public.photo_training_access(t) THEN RAISE EXCEPTION 'Company access denied'; END IF;
IF length(btrim(property))<1 OR hash !~ '^[a-f0-9]{64}$' OR w<=0 OR h<=0 OR split_part(path,'/',1)<>t::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='photo-training-originals' AND name=path AND metadata->>'mimetype' IN ('image/jpeg','image/png','image/webp')) THEN RAISE EXCEPTION 'Invalid original image'; END IF;
INSERT INTO public.photo_training_originals(tenant_id,property_id,sha256,storage_path,file_name,width,height) VALUES(t,btrim(property),hash,path,name,w,h) RETURNING id INTO oid; RETURN oid; END $$;
CREATE OR REPLACE FUNCTION public.photo_training_label_save(o uuid,s text,r jsonb,a jsonb,n boolean,tags_input text[],submit boolean DEFAULT false,expected_revision integer DEFAULT 0) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE orig public.photo_training_originals; lab public.photo_training_labels; region jsonb; point jsonb; lid uuid; ar numeric; idx integer; p1 jsonb; p2 jsonb; BEGIN
SELECT * INTO orig FROM public.photo_training_originals WHERE id=o; IF orig.id IS NULL OR NOT public.photo_training_access(orig.tenant_id) THEN RAISE EXCEPTION 'Company access denied'; END IF;
IF s NOT IN ('shingle','clay_tile','concrete_tile','metal','flat','envelope') OR jsonb_typeof(r)<>'array' OR jsonb_typeof(a)<>'object' OR (n AND jsonb_array_length(r)>0) OR (submit AND NOT n AND jsonb_array_length(r)=0) THEN RAISE EXCEPTION 'Invalid label'; END IF;
FOR region IN SELECT value FROM jsonb_array_elements(r) LOOP
IF NOT public.photo_training_class_valid(s,region->>'cls') OR jsonb_typeof(region->'polygon')<>'array' OR jsonb_array_length(region->'polygon')<3 THEN RAISE EXCEPTION 'Invalid defect polygon'; END IF;
FOR point IN SELECT value FROM jsonb_array_elements(region->'polygon') LOOP IF jsonb_typeof(point->'x')<>'number' OR jsonb_typeof(point->'y')<>'number' OR (point->>'x')::numeric NOT BETWEEN 0 AND 1 OR (point->>'y')::numeric NOT BETWEEN 0 AND 1 THEN RAISE EXCEPTION 'Invalid polygon coordinates'; END IF; END LOOP;
ar:=0; FOR idx IN 0..jsonb_array_length(region->'polygon')-1 LOOP p1:=region->'polygon'->idx; p2:=region->'polygon'->((idx+1)%jsonb_array_length(region->'polygon')); ar:=ar+(p1->>'x')::numeric*(p2->>'y')::numeric-(p2->>'x')::numeric*(p1->>'y')::numeric; END LOOP; IF abs(ar)<0.000002 THEN RAISE EXCEPTION 'Zero-area polygon'; END IF;
END LOOP;
PERFORM pg_advisory_xact_lock(hashtextextended(o::text,0)); SELECT * INTO lab FROM public.photo_training_labels WHERE original_id=o FOR UPDATE;
IF lab.id IS NOT NULL AND (lab.revision<>expected_revision OR lab.status='pending') THEN RAISE EXCEPTION 'Label changed or awaits review; reload first'; END IF;
INSERT INTO public.photo_training_labels(tenant_id,original_id,roof_system,regions,annotations,no_visible_damage,tags,status,labeled_by) VALUES(orig.tenant_id,o,s,r,a,n,coalesce(tags_input,'{}'),CASE WHEN submit THEN 'pending' ELSE 'draft' END,auth.uid()) ON CONFLICT(original_id) DO UPDATE SET roof_system=s,regions=r,annotations=a,no_visible_damage=n,tags=coalesce(tags_input,'{}'),status=CASE WHEN submit THEN 'pending' ELSE 'draft' END,labeled_by=auth.uid(),approved_by=NULL,revision=photo_training_labels.revision+1,updated_at=now() RETURNING id INTO lid;
INSERT INTO public.photo_training_events(tenant_id,label_id,action,revision,snapshot) SELECT tenant_id,id,CASE WHEN submit THEN 'submit' ELSE 'save' END,revision,to_jsonb(l) FROM public.photo_training_labels l WHERE id=lid; RETURN lid; END $$;
CREATE OR REPLACE FUNCTION public.photo_training_label_review(l uuid,decision text,note text,expected_revision integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lab public.photo_training_labels; BEGIN SELECT * INTO lab FROM public.photo_training_labels WHERE id=l FOR UPDATE;
IF lab.id IS NULL OR NOT public.photo_training_access(lab.tenant_id) THEN RAISE EXCEPTION 'Company access denied'; END IF;
IF lab.labeled_by=auth.uid() THEN RAISE EXCEPTION 'A second inspector must review this label'; END IF;
IF lab.status<>'pending' OR lab.revision<>expected_revision OR decision NOT IN ('approve','reject','request_correction') OR (decision<>'approve' AND length(btrim(coalesce(note,'')))=0) THEN RAISE EXCEPTION 'Invalid review or missing correction notes'; END IF;
UPDATE public.photo_training_labels SET status=CASE decision WHEN 'approve' THEN 'approved' WHEN 'reject' THEN 'rejected' ELSE 'correction_requested' END,approved_by=CASE WHEN decision='approve' THEN auth.uid() ELSE NULL END,updated_at=now() WHERE id=l;
INSERT INTO public.photo_training_events(tenant_id,label_id,action,revision,snapshot,notes) VALUES(lab.tenant_id,l,decision,lab.revision,to_jsonb(lab),note); END $$;
CREATE OR REPLACE FUNCTION public.photo_training_dataset_create(t uuid,v text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE did uuid; photos jsonb; splits jsonb; classes jsonb; BEGIN
IF NOT public.photo_training_access(t) OR length(btrim(v))=0 THEN RAISE EXCEPTION 'Company access denied or missing version'; END IF;
SELECT jsonb_agg(jsonb_build_object('photoId',o.id,'sha256',o.sha256,'propertyId',o.property_id,'roofSystem',l.roof_system,'width',o.width,'height',o.height,'fileName',o.id::text||'.'||split_part(o.file_name,'.',array_length(string_to_array(o.file_name,'.'),1)),'storagePath',o.storage_path,'noVisibleDamage',l.no_visible_damage,'regions',l.regions,'status',l.status,'labeledBy',l.labeled_by,'approvedBy',l.approved_by,'tags',l.tags,'labelRevision',l.revision) ORDER BY o.id),jsonb_object_agg(o.id::text,CASE WHEN (('x'||substr(md5(o.property_id),1,8))::bit(32)::bigint%100)<10 THEN 'test' WHEN (('x'||substr(md5(o.property_id),1,8))::bit(32)::bigint%100)<30 THEN 'val' ELSE 'train' END) INTO photos,splits FROM public.photo_training_labels l JOIN public.photo_training_originals o ON o.id=l.original_id AND o.tenant_id=l.tenant_id WHERE l.tenant_id=t AND l.status='approved' AND l.approved_by IS NOT NULL AND l.approved_by<>l.labeled_by;
IF photos IS NULL THEN RAISE EXCEPTION 'No independently approved labels'; END IF;
SELECT jsonb_agg(c ORDER BY c) INTO classes FROM (SELECT DISTINCT rg->>'cls' c FROM jsonb_array_elements(photos) p CROSS JOIN LATERAL jsonb_array_elements(p->'regions') rg) x;
INSERT INTO public.photo_training_datasets(tenant_id,version,manifest) VALUES(t,btrim(v),jsonb_build_object('version',v,'createdAt',now(),'classes',coalesce(classes,'[]'),'photos',photos,'split',splits,'excluded','[]'::jsonb)) RETURNING id INTO did; RETURN did; END $$;
CREATE OR REPLACE FUNCTION public.photo_damage_model_register(t uuid,d uuid,v text,config jsonb,hash text,path text,license text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mid uuid; BEGIN
IF NOT public.photo_training_access(t) OR NOT EXISTS(SELECT 1 FROM public.photo_training_datasets WHERE id=d AND tenant_id=t) THEN RAISE EXCEPTION 'Company access denied'; END IF;
IF hash !~ '^[a-f0-9]{64}$' OR length(btrim(path))=0 OR length(btrim(license))=0 OR length(btrim(v))=0 OR config->>'framework'<>'torchvision-fasterrcnn' OR config->>'pretrained_weights'<>'none' THEN RAISE EXCEPTION 'Invalid checkpoint or unreviewed framework/weights'; END IF;
INSERT INTO public.photo_damage_models(tenant_id,dataset_id,version,configuration,checkpoint_sha256,checkpoint_path,license_evidence) VALUES(t,d,btrim(v),config,hash,path,license) RETURNING id INTO mid; RETURN mid; END $$;
CREATE OR REPLACE FUNCTION public.photo_damage_model_review(m uuid,note text,license_verified boolean,execution_verified boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE model public.photo_damage_models; BEGIN SELECT * INTO model FROM public.photo_damage_models WHERE id=m FOR UPDATE;
IF model.id IS NULL OR NOT public.photo_training_access(model.tenant_id) OR model.created_by=auth.uid() THEN RAISE EXCEPTION 'Independent company reviewer required'; END IF;
IF model.metrics IS NULL OR NOT license_verified OR NOT execution_verified OR length(btrim(coalesce(note,'')))=0 THEN RAISE EXCEPTION 'Evaluation, licensing and independent execution verification required'; END IF;
UPDATE public.photo_damage_models SET license_approved_by=auth.uid(),approved_by=auth.uid(),status='approved',updated_at=now() WHERE id=m;
INSERT INTO public.photo_training_events(tenant_id,model_id,action,notes,snapshot) VALUES(model.tenant_id,m,'model_review',note,jsonb_build_object('license_verified',true,'execution_verified',true,'checkpoint_sha256',model.checkpoint_sha256)); END $$;
CREATE OR REPLACE FUNCTION public.photo_damage_model_activate(m uuid,note text,rollback boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE model public.photo_damage_models; prev uuid; metric jsonb; count_classes integer:=0; BEGIN
SELECT * INTO model FROM public.photo_damage_models WHERE id=m FOR UPDATE; IF model.id IS NULL OR NOT public.photo_training_access(model.tenant_id) THEN RAISE EXCEPTION 'Company access denied'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(model.tenant_id::text,1));
IF model.status NOT IN ('approved','active') OR model.approved_by IS NULL OR model.license_approved_by IS NULL OR length(btrim(coalesce(note,'')))=0 OR model.metrics->>'partition'<>'test' OR coalesce((model.metrics->>'photosEvaluated')::integer,0)<1 THEN RAISE EXCEPTION 'Model is not approved on unseen test properties'; END IF;
FOR metric IN SELECT value FROM jsonb_array_elements(model.metrics->'classes') LOOP count_classes:=count_classes+1; IF coalesce((metric->>'tp')::integer,0)+coalesce((metric->>'fn')::integer,0)<30 OR coalesce((metric->>'precision')::numeric,0)<0.9 OR coalesce((metric->>'recall')::numeric,0)<0.9 THEN RAISE EXCEPTION 'Model fails precision, recall or support gates'; END IF; END LOOP;
IF count_classes=0 THEN RAISE EXCEPTION 'No validated classes'; END IF;
SELECT model_id INTO prev FROM public.photo_damage_deployments WHERE tenant_id=model.tenant_id ORDER BY created_at DESC,id DESC LIMIT 1;
IF rollback AND NOT EXISTS(SELECT 1 FROM public.photo_damage_deployments WHERE tenant_id=model.tenant_id AND model_id=m) THEN RAISE EXCEPTION 'Rollback requires a previously activated model'; END IF;
UPDATE public.photo_damage_models SET status='approved',updated_at=now() WHERE tenant_id=model.tenant_id AND status='active'; UPDATE public.photo_damage_models SET status='active',updated_at=now() WHERE id=m;
INSERT INTO public.photo_damage_deployments(tenant_id,model_id,previous_model_id,action,notes) VALUES(model.tenant_id,m,prev,CASE WHEN rollback THEN 'rollback' ELSE 'promote' END,note); END $$;
REVOKE ALL ON FUNCTION public.photo_training_original_add(uuid,text,text,text,text,integer,integer), public.photo_training_label_save(uuid,text,jsonb,jsonb,boolean,text[],boolean,integer),public.photo_training_label_review(uuid,text,text,integer),public.photo_training_dataset_create(uuid,text),public.photo_damage_model_register(uuid,uuid,text,jsonb,text,text,text),public.photo_damage_model_review(uuid,text,boolean,boolean),public.photo_damage_model_activate(uuid,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.photo_training_original_add(uuid,text,text,text,text,integer,integer),public.photo_training_label_save(uuid,text,jsonb,jsonb,boolean,text[],boolean,integer),public.photo_training_label_review(uuid,text,text,integer),public.photo_training_dataset_create(uuid,text),public.photo_damage_model_register(uuid,uuid,text,jsonb,text,text,text),public.photo_damage_model_review(uuid,text,boolean,boolean),public.photo_damage_model_activate(uuid,text,boolean) TO authenticated,service_role;